package foodchain

import "strings"

// animals are swallowed in order, verse v corresponds to animals[v-1].
var animals = []string{"fly", "spider", "bird", "cat", "dog", "goat", "cow", "horse"}

// comments is the second line of each verse (empty for the fly).
var comments = []string{
	"", // fly
	"It wriggled and jiggled and tickled inside her.",
	"How absurd to swallow a bird!",
	"Imagine that, to swallow a cat!",
	"What a hog, to swallow a dog!",
	"Just opened her throat and swallowed a goat!",
	"I don't know how she swallowed a cow!",
	"She's dead, of course!",
}

// caughtBy is the phrase naming what was swallowed to catch animals[i].
var caughtBy = []string{
	"the fly",
	"the spider that wriggled and jiggled and tickled inside her",
	"the bird",
	"the cat",
	"the dog",
	"the goat",
	"the cow",
}

const dieLine = "I don't know why she swallowed the fly. Perhaps she'll die."

func Verse(v int) string {
	lines := []string{"I know an old lady who swallowed a " + animals[v-1] + "."}
	if c := comments[v-1]; c != "" {
		lines = append(lines, c)
	}
	if v < len(animals) {
		// The cumulative chain, from the current animal down to the fly.
		for i := v - 1; i >= 1; i-- {
			lines = append(lines, "She swallowed the "+animals[i]+" to catch "+caughtBy[i-1]+".")
		}
		lines = append(lines, dieLine)
	}
	return strings.Join(lines, "\n")
}

func Verses(start, end int) string {
	var verses []string
	for v := start; v <= end; v++ {
		verses = append(verses, Verse(v))
	}
	return strings.Join(verses, "\n\n")
}

func Song() string {
	return Verses(1, len(animals))
}

